use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclenum! {
# [doc = " All the different flavors of pattern that Rust recognizes."] # [derive (Clone , Encodable , Decodable , Debug , Walkable)] pub enum PatKind { # [doc = " A missing pattern, e.g. for an anonymous param in a bare fn like `fn f(u32)`."] Missing , # [doc = " Represents a wildcard pattern (`_`)."] Wild , # [doc = " A `PatKind::Ident` may either be a new bound variable (`ref mut binding @ OPT_SUBPATTERN`),"] # [doc = " or a unit struct/variant pattern, or a const pattern (in the last two cases the third"] # [doc = " field must be `None`). Disambiguation cannot be done with parser alone, so it happens"] # [doc = " during name resolution."] Ident (BindingMode , Ident , Option < Box < Pat > >) , # [doc = " A struct or struct variant pattern (e.g., `Variant {x, y, ..}`)."] Struct (Option < Box < QSelf > > , Path , ThinVec < PatField > , PatFieldsRest) , # [doc = " A tuple struct/variant pattern (`Variant(x, y, .., z)`)."] TupleStruct (Option < Box < QSelf > > , Path , ThinVec < Box < Pat > >) , # [doc = " An or-pattern `A | B | C`."] # [doc = " Invariant: `pats.len() >= 2`."] Or (ThinVec < Box < Pat > >) , # [doc = " A possibly qualified path pattern."] # [doc = " Unqualified path patterns `A::B::C` can legally refer to variants, structs, constants"] # [doc = " or associated constants. Qualified path patterns `<A>::B::C`/`<A as Trait>::B::C` can"] # [doc = " only legally refer to associated constants."] Path (Option < Box < QSelf > > , Path) , # [doc = " A tuple pattern (`(a, b)`)."] Tuple (ThinVec < Box < Pat > >) , # [doc = " A `box` pattern."] Box (Box < Pat >) , # [doc = " A `deref` pattern (currently `deref!()` macro-based syntax)."] Deref (Box < Pat >) , # [doc = " A reference pattern (e.g., `&mut (a, b)`)."] Ref (Box < Pat > , Mutability) , # [doc = " A literal, const block or path."] Expr (Box < Expr >) , # [doc = " A range pattern (e.g., `1...2`, `1..2`, `1..`, `..2`, `1..=2`, `..=2`)."] Range (Option < Box < Expr > > , Option < Box < Expr > > , Spanned < RangeEnd >) , # [doc = " A slice pattern `[a, b, c]`."] Slice (ThinVec < Box < Pat > >) , # [doc = " A rest pattern `..`."] # [doc = ""] # [doc = " Syntactically it is valid anywhere."] # [doc = ""] # [doc = " Semantically however, it only has meaning immediately inside:"] # [doc = " - a slice pattern: `[a, .., b]`,"] # [doc = " - a binding pattern immediately inside a slice pattern: `[a, r @ ..]`,"] # [doc = " - a tuple pattern: `(a, .., b)`,"] # [doc = " - a tuple struct/variant pattern: `$path(a, .., b)`."] # [doc = ""] # [doc = " In all of these cases, an additional restriction applies,"] # [doc = " only one rest pattern may occur in the pattern sequences."] Rest , Never , # [doc = " A guard pattern (e.g., `x if guard(x)`)."] Guard (Box < Pat > , Box < Expr >) , # [doc = " Parentheses in patterns used for grouping (i.e., `(PAT)`)."] Paren (Box < Pat >) , # [doc = " A macro pattern; pre-expansion."] MacCall (Box < MacCall >) , # [doc = " Placeholder for a pattern that wasn't syntactically well formed in some way."] Err (ErrorGuaranteed) , }
}